ControlActor = Literal['controller', 'harness', 'scheduler', 'budget_ledger', 'reconciler', 'evaluator']

ContextState = Literal['PROPOSED', 'ACTIVE', 'INVALIDATED', 'CANCELLED']

ExternalCallState = Literal['INTENT_RECORDED', 'DISPATCHED', 'SUCCEEDED', 'FAILED', 'UNKNOWN_OUTCOME', 'CANCELLED']

ConditionObservation = bool | UnknownObservation

ConditionObservations = dict[str, ConditionObservation]

TransitionRejectionCode = Literal['table_version_mismatch', 'revision_conflict', 'unknown_event', 'illegal_transition', 'wrong_actor', 'missing_condition', 'unknown_condition', 'unsatisfied_condition']

class BranchExpectation(TypedDict):
    branch_id: Identifier
    expected_revision: RevisionNumber
    expected_parent: Baseline
    lease_id: Identifier
    expected_lease_epoch: RevisionNumber

class AbsentIncumbent(TypedDict):
    status: Literal['absent']

class KnownIncumbent(TypedDict):
    status: Literal['known']
    program: Baseline
    decision_id: Identifier

IncumbentObservation = AbsentIncumbent | KnownIncumbent | UnknownObservation

class IncumbentExpectation(TypedDict):
    expected_run_revision: EventCursor
    incumbent: IncumbentObservation

class ValidationEligibleResult(TypedDict):
    status: Literal['eligible']
    reason: Literal['contract_satisfied']
    detail: Text

class ValidationRejectedResult(TypedDict):
    status: Literal['rejected']
    reason: Literal['correctness_failed', 'contract_mismatch', 'quality_hard_limit_exceeded', 'prohibited_pattern', 'incomparable_result', 'evidence_revoked']
    detail: Text

class ValidationDeferredResult(TypedDict):
    status: Literal['deferred']
    reason: Literal['missing_evidence', 'unknown_evidence', 'unqualified_evidence', 'missing_quality']
    detail: Text

ValidationResult = ValidationEligibleResult | ValidationRejectedResult | ValidationDeferredResult

class ValidationProposal(TypedDict):
    protocol_version: Literal['kernelcat.lab-control/v1']
    kind: Literal['acceptance_proposal']
    decision: Literal['validation']
    decision_id: Identifier
    run_id: Identifier
    candidate: Baseline
    task_contract_hash: Digest
    evidence: list[ReceiptReference]
    result: ValidationResult

class ArchiveAdmitResult(TypedDict):
    status: Literal['admit']
    reason: Literal['new_structure', 'performance_qualified', 'diversity_policy']
    detail: Text

class ArchiveRejectResult(TypedDict):
    status: Literal['reject']
    reason: Literal['invalid_candidate', 'archive_policy_rejected', 'evidence_revoked']
    detail: Text

class ArchiveDeferResult(TypedDict):
    status: Literal['defer']
    reason: Literal['validation_required', 'archive_policy_unknown']
    detail: Text

ArchiveResult = ArchiveAdmitResult | ArchiveRejectResult | ArchiveDeferResult

class ArchiveProposal(TypedDict):
    protocol_version: Literal['kernelcat.lab-control/v1']
    kind: Literal['acceptance_proposal']
    decision: Literal['archive_admission']
    decision_id: Identifier
    run_id: Identifier
    candidate: Baseline
    task_contract_hash: Digest
    evidence: list[ReceiptReference]
